package day1;


public class Program_Increment {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int n=10;
		n=n+1;
		System.out.println(n);
		
		n++;
		System.out.println(n);
		
		++n;
		System.out.println(n);
		
		System.out.println(n++);
		System.out.println(n);
		
		System.out.println(++n);
		System.out.println(n);
		
	}

}
